---@class eventsApi
events = {}

--- Subscribe to a built-in or custom event. Higher `priority` runs first. Returns a handle for `events.off`.
---@overload fun(event: "on_mod_load", handler: fun(ev: OnModLoadEvent), opts?: EventOptions): integer
---@overload fun(event: "on_mod_unload", handler: fun(ev: OnModUnloadEvent), opts?: EventOptions): integer
---@overload fun(event: "on_level_load", handler: fun(ev: OnLevelLoadEvent), opts?: EventOptions): integer
---@overload fun(event: "on_level_unload", handler: fun(ev: OnLevelUnloadEvent), opts?: EventOptions): integer
---@overload fun(event: "on_update", handler: fun(ev: OnUpdateEvent), opts?: EventOptions): integer
---@overload fun(event: "on_entity_spawn", handler: fun(ev: OnEntitySpawnEvent), opts?: EventOptions): integer
---@overload fun(event: "on_entity_despawn", handler: fun(ev: OnEntityDespawnEvent), opts?: EventOptions): integer
---@overload fun(event: "on_damage", handler: fun(ev: OnDamageEvent), opts?: EventOptions): integer
---@overload fun(event: "on_kill", handler: fun(ev: OnKillEvent), opts?: EventOptions): integer
---@overload fun(event: "on_pickup", handler: fun(ev: OnPickupEvent), opts?: EventOptions): integer
---@overload fun(event: "on_action", handler: fun(ev: OnActionEvent), opts?: EventOptions): integer
---@overload fun(event: "on_mission_event", handler: fun(ev: OnMissionEventEvent), opts?: EventOptions): integer
---@overload fun(event: "on_cvar_changed", handler: fun(ev: OnCvarChangedEvent), opts?: EventOptions): integer
---@overload fun(event: "on_data_reload", handler: fun(ev: OnDataReloadEvent), opts?: EventOptions): integer
---@overload fun(event: "on_shutdown", handler: fun(ev: OnShutdownEvent), opts?: EventOptions): integer
---@param event string
---@param handler fun(ev: table)
---@param opts? EventOptions
---@return integer
function events.on(event, handler, opts) end

--- Remove a subscription.
---@param handle integer
function events.off(handle) end

--- Raise a custom event for all mods (including this one). Built-in event names are reserved. Returns `{cancelled, payload}`.
---@param event string
---@param payload? table
---@return EmitResult
function events.emit(event, payload) end

